	}
	if i.Labels != nil && len(i.Labels.Nodes) > 0 {
		var names []string
		for _, l := range i.Labels.Nodes {
			names = append(names, l.Name)
		}
		fmt.Printf("Labels:   %s\n", strings.Join(names, ", "))
	}
	if i.Description != "" {
		fmt.Printf("\n%s\n", i.Description)
	}
	fmt.Printf("\n%s\n", i.URL)
	return nil
}

