464→func resolveTeamID(client *api.Client, key string) (string, error) {
465→	query := `query {
466→		teams {
467→			nodes { id key }
468→		}
469→	}`
470→	var result struct {
471→		Teams struct {
472→			Nodes []struct {
473→				ID  string `json:"id"`
474→				Key string `json:"key"`
475→			} `json:"nodes"`
476→		} `json:"teams"`
477→	}
478→	if err := client.DoInto(query, nil, &result); err != nil {
479→		return "", err
480→	}
481→	for _, t := range result.Teams.Nodes {
482→		if strings.EqualFold(t.Key, key) {
483→			return t.ID, nil
484→		}
485→	}
486→	return "", fmt.Errorf("team %q not found", key)
487→}
