502→func resolveStateID(client *api.Client, teamID, stateName string) (string, error) {
503→	query := `query($teamId: String!) {
504→		workflowStates(filter: { team: { id: { eq: $teamId } } }) {
505→			nodes { id name }
506→		}
507→	}`
508→	var result struct {
509→		WorkflowStates struct {
510→			Nodes []struct {
511→				ID   string `json:"id"`
512→				Name string `json:"name"`
513→			} `json:"nodes"`
514→		} `json:"workflowStates"`
515→	}
516→	if err := client.DoInto(query, map[string]any{"teamId": teamID}, &result); err != nil {
517→		return "", err
518→	}
519→	for _, s := range result.WorkflowStates.Nodes {
520→		if strings.EqualFold(s.Name, stateName) {
521→			return s.ID, nil
522→		}
523→	}
