===== tests/Feature/Api/AssignmentEndpointTest.php =====
@@ -0,0 +1,55 @@
+<?php
+
+use App\Models\Assignment;
+use Laravel\Passport\Passport;
+use Thunk\Verbs\Facades\Verbs;
+
+beforeEach(function () {
+    Verbs::commitImmediately();
+    $this->user = $this->createUser();
+    $this->agency = $this->createAgency();
+    $this->client = $this->createClient();
+    $this->engagement = $this->createEngagement();
+    $this->role = $this->createRole();
+    $this->assignUserToEngagement();
+});
+
+it('returns active assignments for the authenticated user', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $response = $this->getJson('/api/assignments');
+
+    $response->assertSuccessful()
+        ->assertJsonCount(1, 'data')
+        ->assertJsonPath('data.0.role.name', 'Product Manager')
+        ->assertJsonPath('data.0.engagement.name', 'InterNACHI ongoing consulting')
+        ->assertJsonPath('data.0.client.name', 'InterNACHI')
+        ->assertJsonPath('data.0.agency.name', 'Thunk');
+});
+
+it('does not return archived assignments', function () {
+    $assignment = Assignment::where('user_id', $this->user->id)->first();
+    $assignment->update(['is_archived' => true]);
+
+    Passport::actingAs($this->user, [], 'api');
+
+    $this->getJson('/api/assignments')
+        ->assertSuccessful()
+        ->assertJsonCount(0, 'data');
+});
+
+it('only returns assignments for the authenticated user', function () {
+    $otherUser = $this->createUser('Other User', 'other@thunk.dev');
+    $this->joinAgency($otherUser, $this->agency);
+
+    Passport::actingAs($otherUser, [], 'api');
+
+    $this->getJson('/api/assignments')
+        ->assertSuccessful()
+        ->assertJsonCount(0, 'data');
+});
+
+it('returns 401 when unauthenticated', function () {
+    $this->getJson('/api/assignments')
+        ->assertUnauthorized();
+});

===== tests/Feature/Api/TimeEntryEndpointTest.php =====
@@ -0,0 +1,217 @@
+<?php
+
+use App\Models\Assignment;
+use App\Models\TimeSheetEntry;
+use Illuminate\Support\Str;
+use Laravel\Passport\Passport;
+use Thunk\Verbs\Facades\Verbs;
+
+beforeEach(function () {
+    Verbs::commitImmediately();
+    $this->user = $this->createUser();
+    $this->agency = $this->createAgency();
+    $this->client = $this->createClient();
+    $this->engagement = $this->createEngagement();
+    $this->role = $this->createRole();
+    $this->assignUserToEngagement();
+    $this->assignment = Assignment::where('user_id', $this->user->id)
+        ->where('role_id', $this->role->id)
+        ->first();
+});
+
+it('creates a new time entry', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $clientUuid = Str::uuid()->toString();
+    $date = now()->toDateString();
+
+    $response = $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => $date,
+        'hours' => 2.5,
+        'notes' => 'Worked on feature X',
+        'client_uuid' => $clientUuid,
+    ]);
+
+    $response->assertSuccessful()
+        ->assertJsonPath('data.assignment_id', $this->assignment->id)
+        ->assertJsonPath('data.hours', 2.5)
+        ->assertJsonPath('data.notes', 'Worked on feature X')
+        ->assertJsonPath('data.client_uuid', $clientUuid)
+        ->assertJsonPath('data.date', $date);
+
+    expect(TimeSheetEntry::count())->toBe(1);
+    expect(TimeSheetEntry::first()->hours)->toBe(2.5);
+});
+
+it('adds hours to an existing entry for the same assignment and date', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $date = now();
+    $this->recordTimeSheetEntry($this->user, $date, 4.0, $this->role, $this->engagement, 'Morning work');
+
+    expect(TimeSheetEntry::count())->toBe(1);
+    expect(TimeSheetEntry::first()->hours)->toBe(4.0);
+
+    $clientUuid = Str::uuid()->toString();
+
+    $response = $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => $date->toDateString(),
+        'hours' => 2.0,
+        'notes' => 'Afternoon work',
+        'client_uuid' => $clientUuid,
+    ]);
+
+    $response->assertSuccessful();
+
+    expect(TimeSheetEntry::count())->toBe(1);
+
+    $entry = TimeSheetEntry::first();
+    expect((float) $entry->hours)->toBe(6.0);
+    expect((float) $response->json('data.hours'))->toBe(6.0);
+    expect($entry->notes)->toContain('Morning work');
+    expect($entry->notes)->toContain('Afternoon work');
+});
+
+it('returns existing entry when same client_uuid is submitted again (idempotent)', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $clientUuid = Str::uuid()->toString();
+    $date = now()->toDateString();
+
+    $firstResponse = $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => $date,
+        'hours' => 3.0,
+        'notes' => 'First submission',
+        'client_uuid' => $clientUuid,
+    ]);
+
+    $firstResponse->assertSuccessful();
+
+    expect(TimeSheetEntry::count())->toBe(1);
+    expect(TimeSheetEntry::first()->hours)->toBe(3.0);
+
+    $secondResponse = $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => $date,
+        'hours' => 3.0,
+        'notes' => 'First submission',
+        'client_uuid' => $clientUuid,
+    ]);
+
+    $secondResponse->assertSuccessful()
+        ->assertJsonPath('data.id', $firstResponse->json('data.id'));
+
+    expect(TimeSheetEntry::count())->toBe(1);
+    expect(TimeSheetEntry::first()->hours)->toBe(3.0);
+});
+
+it('validates required fields', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $this->postJson('/api/time-entries', [])
+        ->assertUnprocessable()
+        ->assertJsonValidationErrors(['assignment_id', 'date', 'hours', 'client_uuid']);
+});
+
+it('validates hours must be greater than zero', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => now()->toDateString(),
+        'hours' => 0,
+        'client_uuid' => Str::uuid()->toString(),
+    ])->assertUnprocessable()
+        ->assertJsonValidationErrors(['hours']);
+});
+
+it('validates assignment must exist', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $this->postJson('/api/time-entries', [
+        'assignment_id' => 999999,
+        'date' => now()->toDateString(),
+        'hours' => 1.0,
+        'client_uuid' => Str::uuid()->toString(),
+    ])->assertUnprocessable()
+        ->assertJsonValidationErrors(['assignment_id']);
+});
+
+it('validates client_uuid must be a valid uuid', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => now()->toDateString(),
+        'hours' => 1.0,
+        'client_uuid' => 'not-a-uuid',
+    ])->assertUnprocessable()
+        ->assertJsonValidationErrors(['client_uuid']);
+});
+
+it('prevents submitting to another user assignment', function () {
+    $otherUser = $this->createUser('Other User', 'other@thunk.dev');
+    $this->joinAgency($otherUser, $this->agency);
+
+    Passport::actingAs($otherUser, [], 'api');
+
+    $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => now()->toDateString(),
+        'hours' => 1.0,
+        'client_uuid' => Str::uuid()->toString(),
+    ])->assertForbidden();
+});
+
+it('returns 401 when unauthenticated', function () {
+    $this->postJson('/api/time-entries', [
+        'assignment_id' => $this->assignment->id,
+        'date' => now()->toDateString(),
+        'hours' => 1.0,
+        'client_uuid' => Str::uuid()->toString(),
+    ])->assertUnauthorized();
+});
+
+it('returns time entries since a given timestamp via sync endpoint', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $beforeDate = now()->subDay();
+    $this->recordTimeSheetEntry($this->user, now(), 4.0, $this->role, $this->engagement);
+
+    $response = $this->getJson('/api/time-entries?since='.urlencode($beforeDate->toIso8601String()));
+
+    $response->assertSuccessful()
+        ->assertJsonCount(1, 'data');
+});
+
+it('filters time entries by since parameter on sync endpoint', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $this->recordTimeSheetEntry($this->user, now(), 4.0, $this->role, $this->engagement);
+
+    $futureDate = now()->addDay();
+
+    $response = $this->getJson('/api/time-entries?since='.urlencode($futureDate->toIso8601String()));
+
+    $response->assertSuccessful()
+        ->assertJsonCount(0, 'data');
+});
+
+it('only returns time entries for the authenticated user on sync endpoint', function () {
+    Passport::actingAs($this->user, [], 'api');
+
+    $this->recordTimeSheetEntry($this->user, now(), 4.0, $this->role, $this->engagement);
+
+    $otherUser = $this->createUser('Other User', 'other@thunk.dev');
+    $this->joinAgency($otherUser, $this->agency);
+
+    Passport::actingAs($otherUser, [], 'api');
+
+    $response = $this->getJson('/api/time-entries?since='.urlencode(now()->subDay()->toIso8601String()));
+
+    $response->assertSuccessful()
+        ->assertJsonCount(0, 'data');
+});

