100→func runIssuesList(cmd *cobra.Command, args []string) error {
101→	client, err := api.NewClient()
102→	if err != nil {
103→		return err
104→	}
105→
106→	team, _ := cmd.Flags().GetString("team")
107→	status, _ := cmd.Flags().GetString("status")
108→	assignee, _ := cmd.Flags().GetString("assignee")
109→	limit, _ := cmd.Flags().GetInt("limit")
110→	output, _ := cmd.Root().PersistentFlags().GetString("output")
111→
112→	var filters []string
113→	if team != "" {
114→		filters = append(filters, fmt.Sprintf(`team: { key: { eq: "%s" } }`, team))
115→	}
116→	if status != "" {
117→		filters = append(filters, fmt.Sprintf(`state: { name: { eq: "%s" } }`, status))
118→	}
119→	if assignee == "me" {
120→		filters = append(filters, `assignee: { isMe: { eq: true } }`)
121→	} else if assignee != "" {
122→		filters = append(filters, fmt.Sprintf(`assignee: { displayName: { containsIgnoreCase: "%s" } }`, assignee))
123→	}
124→
125→	filterStr := ""
126→	if len(filters) > 0 {
127→		filterStr = fmt.Sprintf("filter: { %s }", strings.Join(filters, ", "))
128→	}
129→
130→	query := fmt.Sprintf(`query {
131→		issues(first: %d, %s, orderBy: updatedAt) {
132→			nodes {
133→				identifier
134→				title
135→				state { name }
136→				priority
137→				assignee { displayName }
138→				team { key }
139→				updatedAt
140→			}
141→		}
142→	}`, limit, filterStr)
143→
144→	var result struct {
145→		Issues struct {
146→			Nodes []Issue `json:"nodes"`
147→		} `json:"issues"`
148→	}
149→
150→	if err := client.DoInto(query, nil, &result); err != nil {
151→		return err
152→	}
153→
154→	if output == "json" {
155→		return printJSON(result.Issues.Nodes)
156→	}
157→
158→	if len(result.Issues.Nodes) == 0 {
159→		fmt.Println("No issues found.")
160→		return nil
161→	}
162→
163→	for _, issue := range result.Issues.Nodes {
164→		assigneeName := "-"
165→		if issue.Assignee != nil {
166→			assigneeName = issue.Assignee.DisplayName
167→		}
168→		fmt.Printf("%-12s %-14s %-20s %s [%s]\n",
169→			issue.Identifier, issue.State.Name, assigneeName, issue.Title, issue.Team.Key)
170→	}
171→	return nil
172→}
