 1→package api
 2→
 3→import (
 4→	"bytes"
 5→	"encoding/json"
 6→	"fmt"
 7→	"io"
 8→	"net/http"
 9→	"os"
10→)
11→
12→const linearAPI = "https://api.linear.app/graphql"
13→
14→type Client struct {
15→	apiKey     string
16→	httpClient *http.Client
17→}
18→
19→type GraphQLRequest struct {
20→	Query     string         `json:"query"`
21→	Variables map[string]any `json:"variables,omitempty"`
22→}
23→
24→type GraphQLResponse struct {
25→	Data   json.RawMessage `json:"data"`
26→	Errors []struct {
27→		Message string `json:"message"`
28→	} `json:"errors"`
29→}
30→
31→func NewClient() (*Client, error) {
32→	key := os.Getenv("LINEAR_API_KEY")
33→	if key == "" {
34→		return nil, fmt.Errorf("LINEAR_API_KEY not set. Set it in your environment or .env file")
35→	}
36→	return &Client{
37→		apiKey:     key,
38→		httpClient: &http.Client{},
39→	}, nil
40→}
41→
42→func (c *Client) Do(query string, variables map[string]any) (*GraphQLResponse, error) {
43→	reqBody := GraphQLRequest{
44→		Query:     query,
45→		Variables: variables,
46→	}
47→
48→	body, err := json.Marshal(reqBody)
49→	if err != nil {
50→		return nil, fmt.Errorf("marshaling request: %w", err)
51→	}
52→
53→	req, err := http.NewRequest("POST", linearAPI, bytes.NewReader(body))
54→	if err != nil {
55→		return nil, fmt.Errorf("creating request: %w", err)
56→	}
57→
58→	req.Header.Set("Content-Type", "application/json")
59→	req.Header.Set("Authorization", c.apiKey)
60→
61→	resp, err := c.httpClient.Do(req)
62→	if err != nil {
63→		return nil, fmt.Errorf("executing request: %w", err)
64→	}
65→	defer resp.Body.Close()
66→
67→	respBody, err := io.ReadAll(resp.Body)
68→	if err != nil {
69→		return nil, fmt.Errorf("reading response: %w", err)
70→	}
71→
72→	if resp.StatusCode != http.StatusOK {
73→		return nil, fmt.Errorf("API returned status %d: %s", resp.StatusCode, string(respBody))
74→	}
75→
76→	var gqlResp GraphQLResponse
77→	if err := json.Unmarshal(respBody, &gqlResp); err != nil {
78→		return nil, fmt.Errorf("parsing response: %w", err)
79→	}
80→
81→	if len(gqlResp.Errors) > 0 {
82→		return nil, fmt.Errorf("GraphQL error: %s", gqlResp.Errors[0].Message)
83→	}
84→
85→	return &gqlResp, nil
86→}
87→
88→// DoInto executes a query and unmarshals the data field into target.
89→func (c *Client) DoInto(query string, variables map[string]any, target any) error {
90→	resp, err := c.Do(query, variables)
91→	if err != nil {
92→		return err
93→	}
94→	return json.Unmarshal(resp.Data, target)
95→}
