562→func resolveProjectID(client *api.Client, name string) (string, error) {
563→	query := fmt.Sprintf(`query {
564→		projects(filter: { name: { containsIgnoreCase: "%s" } }) {
565→			nodes { id name }
566→		}
567→	}`, name)
568→	var result struct {
569→		Projects struct {
570→			Nodes []struct {
571→				ID   string `json:"id"`
572→				Name string `json:"name"`
573→			} `json:"nodes"`
574→		} `json:"projects"`
575→	}
576→	if err := client.DoInto(query, nil, &result); err != nil {
577→		return "", err
578→	}
579→	if len(result.Projects.Nodes) == 0 {
580→		return "", fmt.Errorf("project %q not found", name)
581→	}
582→	// Prefer exact (case-insensitive) match
583→	for _, p := range result.Projects.Nodes {
584→		if strings.EqualFold(p.Name, name) {
585→			return p.ID, nil
586→		}
587→	}
588→	// Fall back to first partial match
589→	return result.Projects.Nodes[0].ID, nil
