	filterStr := ""
	if status != "" {
		filterStr = fmt.Sprintf(`filter: { status: { eq: "%s" } }`, status)
	}

	query := fmt.Sprintf(`query {
		initiatives(%s) {
			nodes {
				id
				name
				status
				health
				owner { displayName }
				targetDate
				projects { nodes { id name } }
				parentInitiative { id name }
				url
			}
		}
	}`, filterStr)

	var result struct {
		Initiatives struct {
