			ownerName = i.Owner.DisplayName
		}
		projectCount := 0
		if i.Projects != nil {
			projectCount = len(i.Projects.Nodes)
		}
		healthStr := ""
		if i.Health != "" {
			healthStr = fmt.Sprintf(" [%s]", i.Health)
