		Initiatives struct {
			Nodes []Initiative `json:"nodes"`
		} `json:"initiatives"`
	}

	if err := client.DoInto(query, nil, &result); err != nil {
		return nil, err
	}

	if len(result.Initiatives.Nodes) == 0 {
		return nil, fmt.Errorf("initiative %q not found", nameOrID)
