func init() {
	startCmd.Flags().StringP("prompt", "p", "", "Initial prompt to send to Claude Code")
	startCmd.Flags().Bool("resume", false, "Resume the most recent Claude Code conversation")
	rootCmd.AddCommand(startCmd)
