func runStart(cmd *cobra.Command, args []string) error {
	prompt, _ := cmd.Flags().GetString("prompt")
	resume, _ := cmd.Flags().GetBool("resume")

	repo := args[0]

	// Parse org/repo from various formats
	org, repoName := parseRepo(repo)
