	}

	// Clone if needed
	if _, err := os.Stat(repoDir); os.IsNotExist(err) {
		fmt.Printf("Cloning %s into %s...\n", fullRepo, repoDir)
		if err := os.MkdirAll(srcDir, 0755); err != nil {
			return fmt.Errorf("creating src directory: %w", err)
		}
