		if err := killCmd.Run(); err != nil {
			fmt.Println("No active sessions to stop.")
			return nil
		}
		fmt.Println("All sessions stopped.")
		return nil
	}

	if len(args) == 0 {
		return fmt.Errorf("specify a session name or use --all")
