package cmd

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

var orchCmd = &cobra.Command{
	Use:   "orch",
	Short: "Start the orchestrator Claude Code session",
	Long: `Launch Claude Code in a tmux session named "orch" rooted at ~/orch.

This is the main orchestrator session that manages all other sessions.

Examples:
  session orch
  session orch -p "Check inbox and prioritize tasks"
  session orch --resume
  session orch --dangerously-skip-permissions`,
	Args: cobra.NoArgs,
	RunE: runOrch,
}

func init() {
	orchCmd.Flags().StringP("prompt", "p", "", "Initial prompt to send to Claude Code")
	orchCmd.Flags().Bool("resume", false, "Resume the most recent Claude Code conversation")
	orchCmd.Flags().Bool("dangerously-skip-permissions", false, "Skip all permission checks in the spawned session")
	rootCmd.AddCommand(orchCmd)
}

func runOrch(cmd *cobra.Command, args []string) error {
	prompt, _ := cmd.Flags().GetString("prompt")
	resume, _ := cmd.Flags().GetBool("resume")
	skipPerms, _ := cmd.Flags().GetBool("dangerously-skip-permissions")

	sessionName := "orch"

	// Check if tmux session already exists
	if sessionExists(sessionName) {
		fmt.Printf("Session %q already exists. Use 'session attach %s' to connect.\n", sessionName, sessionName)
		return nil
	}

	// Ensure inbox directory exists
	os.MkdirAll(inboxDir, 0755)

	// Build the claude command
	claudeArgs := []string{}
	if resume {
		claudeArgs = append(claudeArgs, "--resume")
	}
	if skipPerms {
		claudeArgs = append(claudeArgs, "--dangerously-skip-permissions")
	}

	claudeCmd := "claude " + strings.Join(claudeArgs, " ")

	if prompt == "" && !resume {
		prompt = "You are the orchestrator. Read CLAUDE.md and let me know you're ready."
	}

	// Unset CLAUDECODE so the spawned session doesn't inherit it
	envSetup := "unset CLAUDECODE"

	// Create tmux session rooted in ~/orch
	tmuxCmd := exec.Command("tmux", "new-session", "-d", "-s", sessionName, "-c", orchDir)
	tmuxCmd.Stdout = os.Stdout
	tmuxCmd.Stderr = os.Stderr
	if err := tmuxCmd.Run(); err != nil {
		return fmt.Errorf("creating tmux session: %w", err)
	}

	// Source env vars and launch claude
	time.Sleep(500 * time.Millisecond)
	launchCmd := fmt.Sprintf("%s && %s", envSetup, claudeCmd)
	sendClaude := exec.Command("tmux", "send-keys", "-t", sessionName, launchCmd, "Enter")
	if err := sendClaude.Run(); err != nil {
		return fmt.Errorf("launching claude: %w", err)
	}

	if prompt != "" {
		fmt.Printf("Waiting for Claude to start...")
		promptSent := false
		for i := 0; i < 60; i++ {
			time.Sleep(1 * time.Second)
			out, _ := exec.Command("tmux", "capture-pane", "-t", sessionName, "-p").Output()
			pane := string(out)

			// Handle trust prompt — press Enter to confirm
			if strings.Contains(pane, "Yes, I trust this folder") {
				exec.Command("tmux", "send-keys", "-t", sessionName, "Enter").Run()
				fmt.Print("(trusted).")
				continue
			}

			// Claude is ready when it shows the input prompt
			lines := strings.Split(strings.TrimSpace(pane), "\n")
			if len(lines) > 0 {
				lastLine := strings.TrimSpace(lines[len(lines)-1])
				if lastLine == ">" || lastLine == "❯" || lastLine == "" {
					if strings.Contains(pane, "Tips:") || strings.Contains(pane, "/help") || strings.Contains(pane, "What can I") {
						fmt.Println(" ready!")
						time.Sleep(500 * time.Millisecond)
						sendPrompt := exec.Command("tmux", "send-keys", "-t", sessionName, prompt, "Enter")
						if err := sendPrompt.Run(); err != nil {
							return fmt.Errorf("sending prompt: %w", err)
						}
						promptSent = true
						break
					}
				}
			}
			fmt.Print(".")
		}
		if !promptSent {
			fmt.Println(" timed out, sending prompt anyway.")
			time.Sleep(500 * time.Millisecond)
			exec.Command("tmux", "send-keys", "-t", sessionName, prompt, "Enter").Run()
		}
	}

	fmt.Printf("Started orchestrator session %q in %s\n", sessionName, orchDir)
	fmt.Printf("Attach with: session attach %s\n", sessionName)
	return nil
}

package cmd

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

var watchdogCmd = &cobra.Command{
	Use:   "watchdog",
	Short: "Check if the orch session is alive and restart it if not",
	Long: `Designed to be run from cron. Checks if the "orch" tmux session exists.
If it does, exits silently. If not, restarts it with --dangerously-skip-permissions --resume.

Logs restarts to ~/orch/inbox/watchdog.log with timestamps.

Example crontab entry:
  */5 * * * * /usr/local/bin/session watchdog`,
	Args: cobra.NoArgs,
	RunE: runWatchdog,
}

func init() {
	rootCmd.AddCommand(watchdogCmd)
}

func runWatchdog(cmd *cobra.Command, args []string) error {
	sessionName := "orch"

	// If session exists, exit silently
	if sessionExists(sessionName) {
		return nil
	}

	// Log the restart
	logFile := filepath.Join(inboxDir, "watchdog.log")
	os.MkdirAll(inboxDir, 0755)
	timestamp := time.Now().Format("2006-01-02 15:04:05")
	logEntry := fmt.Sprintf("[%s] Orch session not found, restarting...\n", timestamp)

	f, err := os.OpenFile(logFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return fmt.Errorf("opening watchdog log: %w", err)
	}
	f.WriteString(logEntry)
	f.Close()

	// Start the orch session with --dangerously-skip-permissions --resume
	claudeCmd := "claude --resume --dangerously-skip-permissions"
	envSetup := "unset CLAUDECODE"
	prompt := "You are the orchestrator. Read CLAUDE.md and let me know you're ready."

	// Create tmux session rooted in ~/orch
	tmuxCmd := exec.Command("tmux", "new-session", "-d", "-s", sessionName, "-c", orchDir)
	tmuxCmd.Stdout = os.Stdout
	tmuxCmd.Stderr = os.Stderr
	if err := tmuxCmd.Run(); err != nil {
		logFailure(logFile, timestamp, "creating tmux session", err)
		return fmt.Errorf("creating tmux session: %w", err)
	}

	// Launch claude
	time.Sleep(500 * time.Millisecond)
	launchStr := fmt.Sprintf("%s && %s", envSetup, claudeCmd)
	sendClaude := exec.Command("tmux", "send-keys", "-t", sessionName, launchStr, "Enter")
	if err := sendClaude.Run(); err != nil {
		logFailure(logFile, timestamp, "launching claude", err)
		return fmt.Errorf("launching claude: %w", err)
	}

	// Wait for Claude to be ready and send prompt
	for i := 0; i < 60; i++ {
		time.Sleep(1 * time.Second)
		out, _ := exec.Command("tmux", "capture-pane", "-t", sessionName, "-p").Output()
		pane := string(out)

		// Handle trust prompt
		if strings.Contains(pane, "Yes, I trust this folder") {
			exec.Command("tmux", "send-keys", "-t", sessionName, "Enter").Run()
			continue
		}

		// Claude is ready when it shows the input prompt
		lines := strings.Split(strings.TrimSpace(pane), "\n")
		if len(lines) > 0 {
			lastLine := strings.TrimSpace(lines[len(lines)-1])
			if lastLine == ">" || lastLine == "❯" || lastLine == "" {
				if strings.Contains(pane, "Tips:") || strings.Contains(pane, "/help") || strings.Contains(pane, "What can I") {
					time.Sleep(500 * time.Millisecond)
					exec.Command("tmux", "send-keys", "-t", sessionName, prompt, "Enter").Run()
					logSuccess(logFile, timestamp)
					return nil
				}
			}
		}
	}

	// Timed out waiting, send prompt anyway
	time.Sleep(500 * time.Millisecond)
	exec.Command("tmux", "send-keys", "-t", sessionName, prompt, "Enter").Run()
	logSuccess(logFile, timestamp)
	return nil
}

func logFailure(logFile, timestamp, step string, err error) {
	f, ferr := os.OpenFile(logFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if ferr != nil {
		return
	}
	defer f.Close()
	f.WriteString(fmt.Sprintf("[%s] Failed %s: %v\n", timestamp, step, err))
}

func logSuccess(logFile, timestamp string) {
	f, err := os.OpenFile(logFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return
	}
	defer f.Close()
	f.WriteString(fmt.Sprintf("[%s] Orch session restarted successfully.\n", timestamp))
}

package cmd

import (
	"fmt"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

var listCmd = &cobra.Command{
	Use:   "list",
	Short: "List active Claude Code sessions",
	Long: `Show all active tmux sessions with heartbeat status.

Examples:
  session list`,
	Aliases: []string{"ls"},
	RunE:    runList,
}

func init() {
	rootCmd.AddCommand(listCmd)
}

type heartbeatInfo struct {
	Status      string
	LastActive  string
	CurrentTask string
}

func parseHeartbeatFile(path string) (*heartbeatInfo, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	info := &heartbeatInfo{}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "Status:") {
			info.Status = strings.TrimSpace(strings.TrimPrefix(line, "Status:"))
		} else if strings.HasPrefix(line, "Last active:") {
			info.LastActive = strings.TrimSpace(strings.TrimPrefix(line, "Last active:"))
		} else if strings.HasPrefix(line, "Current task:") {
			info.CurrentTask = strings.TrimSpace(strings.TrimPrefix(line, "Current task:"))
		}
	}
	return info, nil
}

func formatTimeAgo(isoTimestamp string) string {
	// Try parsing common ISO 8601 formats
	formats := []string{
		time.RFC3339,
		"2006-01-02T15:04:05Z",
		"2006-01-02T15:04:05-07:00",
		"2006-01-02T15:04:05",
	}

	var t time.Time
	var err error
	for _, f := range formats {
		t, err = time.Parse(f, isoTimestamp)
		if err == nil {
			break
		}
	}
	if err != nil {
		return isoTimestamp
	}

	dur := time.Since(t)
	if dur < 0 {
		return "just now"
	}

	seconds := dur.Seconds()
	if seconds < 60 {
		return fmt.Sprintf("%ds ago", int(seconds))
	}
	minutes := math.Floor(dur.Minutes())
	if minutes < 60 {
		return fmt.Sprintf("%.0fm ago", minutes)
	}
	hours := math.Floor(dur.Hours())
	if hours < 24 {
		return fmt.Sprintf("%.0fh ago", hours)
	}
	days := math.Floor(hours / 24)
	return fmt.Sprintf("%.0fd ago", days)
}

func getHeartbeat(sessionName string) *heartbeatInfo {
	path := filepath.Join(inboxDir, fmt.Sprintf("heartbeat-%s.md", sessionName))
	info, err := parseHeartbeatFile(path)
	if err != nil {
		return nil
	}
	return info
}

func runList(cmd *cobra.Command, args []string) error {
	out, err := exec.Command("tmux", "list-sessions", "-F", "#{session_name}").Output()
	if err != nil {
		// tmux returns error when no server is running
		fmt.Println("No active sessions.")
		return nil
	}

	lines := strings.TrimSpace(string(out))
	if lines == "" {
		fmt.Println("No active sessions.")
		return nil
	}

	fmt.Printf("%-20s %-12s %-14s %s\n", "SESSION", "STATUS", "LAST ACTIVE", "CURRENT TASK")
	for _, sessionName := range strings.Split(lines, "\n") {
		sessionName = strings.TrimSpace(sessionName)
		if sessionName == "" {
			continue
		}

		hb := getHeartbeat(sessionName)
		if hb != nil {
			lastActive := formatTimeAgo(hb.LastActive)
			status := hb.Status
			if status == "" {
				status = "unknown"
			}
			task := hb.CurrentTask
			if task == "" {
				task = "-"
			}
			fmt.Printf("%-20s %-12s %-14s %s\n", sessionName, status, lastActive, task)
		} else {
			fmt.Printf("%-20s %-12s %-14s %s\n", sessionName, "-", "(no heartbeat)", "-")
		}
	}
	return nil
}

